/bin/zsh -lc "python3 -c 'import csv,json
from pathlib import Path
p=Path(\"project\")
codes=json.loads((p/\"status-code-contract.json\").read_text())[\"status_codes\"]
source={}
for row in csv.DictReader((p/\"commits.csv\").open()):
    if row[\"result\"]"'!="committed": continue
    key=row["key"]
    if row["operation"]=="delete": source.pop(key,None)
    else: source[key]=(row["incarnation"],int(row["revision"]),codes[row["status_text"]])
actual={row["key"]:(row["incarnation"],int(row["source_rev"]),int(row["status_code"]),int(row["mapped_rev"])) for row in csv.DictReader((p/"derived.csv").open())}
expected={key:(inc,rev,code,rev) for key,(inc,rev,code) in source.items()}
print("expected",expected)
print("actual",actual)
print("missing",sorted(set(expected)-set(actual)))
print("extra",sorted(set(actual)-set(expected)))
print("mismatched",{key:(expected[key],actual[key]) for key in set(expected)&set(actual) if expected[key]!=actual[key]})'"'"

